using FluentValidation; using LibraryInventory.Api.Dtos.Checkouts; using LibraryInventory.Api.Extensions; using LibraryInventory.Core.Commands; using LibraryInventory.Core.Entities; using LibraryInventory.Core.Interfaces; using Microsoft.AspNetCore.Mvc;
namespace LibraryInventory.Api.Controllers; [ApiController][Route("api/[controller]")] public class CheckoutsController(ICheckoutService service,TimeProvider time):ControllerBase{[HttpPost(Name="CreateCheckout")]public async Task<IActionResult>Create(CreateCheckoutDto dto,IValidator<CreateCheckoutDto>v,CancellationToken ct){var vr=await v.ValidateAsync(dto,ct);if(!vr.IsValid)return this.ToValidationProblem(vr);var r=await service.CheckoutAsync(new(dto.BookId,dto.MemberId),ct);return r.IsSuccess?CreatedAtAction(nameof(GetById),new{id=r.Data!.CheckoutId},ToDto(r.Data)):this.ToFailure(r.Error,r.Message);}[HttpGet("{id:int}")]public async Task<IActionResult>GetById(int id,CancellationToken ct){var r=await service.GetByIdAsync(id,ct);return r.IsSuccess?Ok(ToDto(r.Data!)):this.ToFailure(r.Error,r.Message);}[HttpPut("{id:int}/return")]public async Task<IActionResult>Return(int id,CancellationToken ct){var r=await service.ReturnAsync(id,ct);return r.IsSuccess?Ok(ToDto(r.Data!)):this.ToFailure(r.Error,r.Message);}[HttpGet("overdue")]public async Task<IActionResult>Overdue(CancellationToken ct){var now=time.GetUtcNow().UtcDateTime;return Ok((await service.GetOverdueAsync(ct)).Select(x=>ToDto(x,now)));}CheckoutResponseDto ToDto(Checkout c)=>ToDto(c,time.GetUtcNow().UtcDateTime);static CheckoutResponseDto ToDto(Checkout c,DateTime now)=>new(c.CheckoutId,c.BookId,c.MemberId,c.CheckedOutAtUtc,c.DueDateUtc,c.ReturnedAtUtc,c.IsOverdue(now),c.DaysOverdue(now));}
